DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.undo_push(uuid)'::regprocedure) INTO definition; definition=replace(definition,'miss_streak=lg.misses_before,version=version+1,paused_reason=NULL','miss_streak=lg.misses_before,last_decision_at=(SELECT max((evidence_log->>''date'')::date) FROM public.push_log prev CROSS JOIN LATERAL jsonb_array_elements(prev.evidence) evidence_log WHERE prev.athlete_id=lg.athlete_id AND prev.lift=lg.lift AND prev.id<>lg.id AND prev.undone_at IS NULL),version=version+1,paused_reason=NULL'); EXECUTE definition; END $$;